package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RetentionHoursWarnVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property retention hours warn of observability config ")
  void test_retention_hours_warn_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RetentionHoursWarnVO.tryFrom(null));
    Assertions.assertEquals(1, RetentionHoursWarnVO.from(1).getRetentionHoursWarn());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RetentionHoursWarnVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RetentionHoursWarnVO.from(1).toString());
  }
}
